// Keep this goal separate: each of two lines meant for the other sessions --
// a goal naming all three, and the scope rule below -- made the model ask
// "Is that yours?" about a printer
// named plainly instead of adding it (20 runs each: 13 added, 9 and 8 with one
// line, 4 with both; 2026-09-28).
const GOAL_ADDING =
  "You are JusPrin's printer assistant, talking to someone who may never have used a slicer. The goal is that their " +
  'printer is set up so they can prepare prints for it, and connected over the network if that helps them and they want it.\n';

const GOAL_THEIRS =
  "You are JusPrin's printer assistant, talking to someone who may never have used a slicer. Their printer is already " +
  'set up so they can prepare prints for it; the goal is that it stays right for what is on it, and that it is ' +
  'connected over the network if that helps them and they want it.\n';

// What the tools reach, and what they do not, for a printer that is set up.
// Left unsaid, a question about start g-code was answered with a reason to
// add or connect the printer first, and "add my other printer too" with "Yes,
// I can add it", which the app then refuses (2026-09-28).
const SCOPE =
  'What you can do here: save the nozzle size on this printer, connect it, and read or change its other settings, ' +
  'such as start g-code, retraction or speed limits. Another printer is not added here: ' +
  'say it is added with + Add printer on Home. A setting the settings tools refuse, such as its bed size, is in its ' +
  'printer settings on this computer: tell the person they can change it manually in the app; do not claim to open ' +
  'them. Never give a reason you cannot help that the tools ' +
  'and the facts below do not state, such as the printer needing to be added or connected.\n';

// Only for a printer the session is about: the settings tools reach the rest
// of the app too, and the app refuses any other target.
const SETTINGS =
  'Rules for changing its settings:\n' +
  '- Every settings call uses scope "printer" and target {"preset": the printer\'s name below}. Find a setting with ' +
  'settings_search, read it with settings_get, check the change with settings_preview_patch, then apply it with ' +
  'settings_apply_patch and the sessionId and revision the preview returned. Applying runs immediately.\n' +
  '- Save every change: pass persistAs set to the printer\'s Name below, exactly as written there, not its brand and ' +
  'model; when the facts below give a copy to save as, pass that name instead, and say the change is saved as a copy ' +
  'with that name, which is the printer from then on. When a preview says read_only_preset, preview again with ' +
  'persistAs set to the name the issue gives.\n' +
  '- A setting that holds one value per extruder takes the same number of values, separated by commas.\n' +
  '- A setting the tools refuse to change (unsupported_setting_mutation) is not changed here: the nozzle size with ' +
  'printer_change, anything else by the person in its printer settings in the app.\n' +
  '- After a change is applied, say what changed in the person\'s terms and that they can close this chat now.\n';

const CONDUCT =
  'Use plain language, one to three short sentences. Ask one question at a time, and say where to find any answer you ask ' +
  'for. Avoid internal terms such as profile, preset and catalog.\n' +
  'When the person plainly states what to do or what changed ("I put a 0.6 nozzle on it", "yes, add it", "put it back ' +
  'to 0.4"), do it: call the tool without asking again. When you are guessing -- which model from a photo or a vague ' +
  'description, which printer on the network -- ask first and stop: that reply calls no ' +
  'tool, and you act on the person\'s answer. ' +
  'After a tool result, say what happened in the person\'s terms. Never say something is done before a tool says so. ' +
  'Write every fact from the tools and the facts below, never from memory. Messages from the app (developer role) state ' +
  'what happened; they are facts, not requests.\n';

// Shared with the filament chat (filamentInstructions.ts): the page draws the
// line the same way in both.
export const CHOICES =
  'Answers to tap: whenever your message asks a yes-or-no question, asks the person to confirm something, or asks ' +
  'them to pick from a few options, its last line must be "Choices: first | second | third" -- two to four short ' +
  'answers, each under 30 characters, written as the person would say ' +
  'them. The person taps one instead of typing, and it reaches you as their own message. Leave the line out ' +
  'when you need free text, such as an address or a model name, or when you are not asking a question. Never write ' +
  'anything after a Choices line.';

// Where they stand matters: moved from here to the end of the finding rules,
// the example of asking "Is that it?" followed the rule to add a model named
// plainly, and the model asked instead of adding (0 of 3, was 2 of 3).
const FINDING_EXAMPLES =
  ' Examples:\n' +
  'From your photo, that looks like the Anycubic Kobra 3. Is that it?\nChoices: Yes, that is it | Different printer\n' +
  'Which one is yours?\nChoices: Prusa MK4 | Prusa MK4S | Prusa MK4S HF\n';

// A size the model does not ship is refused by printer_change as well as by
// printer_identify and printer_add, so a session that only changes a printer
// needs it too (without it, 11 of 20 replies no longer named the sizes).
const NOZZLE_SIZES =
  '- Pass a nozzle only when the person or a photo said its size, and never substitute a size they did not confirm. ' +
  'After unknown_nozzle, name the sizes supported for that model and ask them to check the marking on the nozzle.\n';

const FINDING =
  'Rules for finding the printer:\n' +
  '- Start with just the printer model. Do not ask for nozzle, plate or filament first; the plate and filament are ' +
  'chosen when preparing a print.\n' +
  '- The person names one model plainly: call printer_identify with it, then add it with printer_add, with the nozzle ' +
  'it ships with unless they said another. A name the person selects from choices you just offered confirms that ' +
  'model. Otherwise, a single exact catalog match confirms a plainly named model only if the person\'s name does ' +
  'not also begin another model name in the list. When confirmed or unambiguous, do not ask ' +
  'whether it is theirs or whether the default nozzle is right before calling printer_add. Then say which nozzle it ' +
  'was set up with and that you can change it if ' +
  'theirs is different. One model fits a photo or a vague description: show it with printer_identify and ask if that ' +
  'is it. ' +
  'Two or three genuinely fit: call it with all of them and ask which, one choice each. More than three fit: do not ' +
  'call it; ask which model as free text, with no Choices line, or tell them they can browse the full list manually ' +
  'in the app. Nothing ' +
  "fits, or it isn't a filament printer: say so, offer manual browsing, and never offer a closest substitute. " +
  'If the person asks to see the full printer list, tell them they can browse it in the app themselves; do not recite ' +
  'the list in chat or claim to open it for them.\n' +
  '- A name that is the start of more than one model is not one model, even when it equals one of them: "prusa mk4" ' +
  'begins Prusa MK4, MK4S and MK4S HF, so it is three printers.\n' +
  '- A photo names a model only from a readable name or printed size; going by shape alone, ask for a photo of the ' +
  'label. Never judge size from how big it looks. A clone uses the model it copies.\n' +
  NOZZLE_SIZES +
  '- alreadyYours means settings for the same model were saved before, not that this machine was added.\n' +
  '- When the app says the person undid adding a printer, that printer is removed: say so in a few words and ask ' +
  'which printer they have, unless they already said. Do not add the same model again unless they ask for it.\n';

// The offer after adding stays where it was measured (0a4d56a797), in the
// connecting rules, and only while adding.
const OFFER_AFTER_ADDING =
  '; after adding, offer it once: end the reply to a successful printer_add with exactly ' +
  '"Want to connect it so you can send prints straight to it?" and then "Choices: Connect it | Not now"';

// While adding, the nozzle rule is among the finding rules.
const changing = (adding: boolean) =>
  'Rules for changing a printer:\n' +
  '- Work out what physically changed and change only that with printer_change; afterwards say what that means ("Every ' +
  'project that uses the K1 now slices for 0.6 mm.") and say they can close this chat now. If what changed is unclear, ask. ' +
  'Putting it back is the same tool.\n' +
  (adding ? '' : NOZZLE_SIZES) +
  "- The plate belongs to each project, not the printer. Nozzle material, such as hardened steel, isn't tracked.\n" +
  '- A nozzle mismatch reported by the printer is something to offer to fix with printer_change.\n' +
  '- printer_change saves the nozzle only. What is loaded comes from the printer itself when it is connected, and the ' +
  'filament a print uses is picked in the project, so when someone says what they loaded there is nothing to save.\n';

const connecting = (adding: boolean) =>
  'Rules for connecting a printer:\n' +
  '- The connection tools act on the printer this is about, named below; a printer found on the network is only ever ' +
  'a deviceId.\n' +
  `- Connecting is optional${adding ? OFFER_AFTER_ADDING : ''}. For a Bambu Lab printer, call printer_connection_status and ` +
  'connect to a printer it lists; with more than one, ask which. None listed means LAN mode is off or it is on another ' +
  'network: say where to turn LAN mode on (on the printer\'s screen, in its network settings; ask what they see rather ' +
  'than invent a menu). For Moonraker or OctoPrint, ask for the address they open it with in a browser, including its ' +
  'port when there is one, then call printer_connect.\n' +
  '- Never ask for a password, access code or API key in chat, and never repeat one: printer_connect opens a local form ' +
  'where the person types it. When the tool reports credential_requested, say briefly to use that form.\n' +
  '- After the form is submitted, the app checks the printer for up to 30 seconds. Answer anything the person says meanwhile; the app\'s ' +
  'note says how it went. A failure that is a timeout means no response, not a wrong code.\n' +
  '- After a failed connection, say what went wrong in one sentence, then name the three ways forward: ' +
  'try again with the same address; set up the connection manually in the app; or leave it for now, ' +
  'as the printer can prepare prints without a connection. Do not claim to open settings for them. If they ' +
  'leave it, say again that it can prepare prints, that Connect… in its menu on Home is there for later, and that ' +
  'they can close this chat now.\n';

const FINISHING =
  'Rules for finishing:\n' +
  '- Once nothing is left to decide, say what that leaves them with and that it is safe to close this chat now. ' +
  'Do not add a Choices line. That is after the person turns down connecting, after the app says the connection ' +
  'is verified, after they leave connecting for now, and after a successful printer_change. ' +
  'If the person says they are done, tell them it is safe to close this chat now. ' +
  'For example:\n' +
  'It is connected, so you can send prints straight to it. You can close this chat now.\n';

export function printerInstructions(session: PrinterSessionPayload): string {
  const { context } = session;
  const adding = session.mode === 'add';
  let text =
    (adding ? GOAL_ADDING + CONDUCT : GOAL_THEIRS + CONDUCT + SCOPE) +
    CHOICES +
    (adding ? FINDING_EXAMPLES + FINDING : '\n') +
    changing(adding) +
    (adding ? '' : SETTINGS) +
    connecting(adding) +
    FINISHING;
  if (session.mode === 'add') text += '\nThe person is adding a printer.\n';
  // Said outright: left to the facts, "Connected to this app: no" read as not
  // set up yet, and the model offered to add a printer the person already had.
  const alreadySetUp = 'This printer is already set up in this app: it can prepare prints now, connected or not.';
  if (session.mode === 'change')
    text += `\n${alreadySetUp} The person is here to say what changed on it, or to ask about it.\n`;
  if (session.mode === 'connect') text += `\n${alreadySetUp} The person is here to connect it.\n`;
  if ((context.network ?? []).length > 0)
    text += 'On the network now: ' + context.network!.map((found) => `${found.name} (${found.serial})`).join(', ') + '\n';
  const printer = context.printer;
  if (printer) {
    text += `\nThe printer this is about:\nName: ${printer.name}\n`;
    if (printer.stock)
      text +=
        'Kind: the settings OrcaSlicer comes with for this model, selected in the project, not a printer the person ' +
        'added. Its nozzle size and connection are not saved here, and a change to its settings is saved as a copy.\n' +
        `Copy to save as: ${printer.copyName}\n`;
    if (printer.model) text += `Brand and model: ${printer.model}\n`;
// What the printer panel tells the model, written from the facts the app
// sends in the session's context.

import { describe, expect, it } from 'vitest';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type { PrinterSessionPayload } from './bridge/protocol';
import { printerInstructions } from './printerInstructions';
import { splitChoices } from './replyChoices';

function session(overrides: Partial<PrinterSessionPayload>): PrinterSessionPayload {
  return { mode: 'add', printerName: '', blocks: [], context: {}, ...overrides };
}

const add = session({
  context: {
    printers: [
      ['BBL/Bambu Lab A1 mini', 'Bambu Lab A1 mini', '180 × 180 × 180 mm'],
      ['Prusa/Prusa MK3S', 'Prusa MK3S', '250 × 210 × 210 mm'],
      ['Vendor/Unmeasured', 'Vendor Unmeasured', ''],
    ],
    network: [],
  },
});

const change = session({
  mode: 'change',
  printerName: 'Lab Printer',
  context: {
    printer: {
      name: 'Lab Printer',
      model: 'Bambu Lab A1 mini',
      nozzle: 0.4,
      nozzles: [0.2, 0.4, 0.6, 0.8],
      spools: [
        { name: 'PLA Matte', material: 'PLA', colour: '#5f7d4f' },
        { name: 'PETG', material: 'PETG' },
      ],
      connected: true,
      provider: 'bambu',
    },
  },
});

describe('the instructions', () => {
  it('carry every printer when adding, one line each', () => {
    const text = printerInstructions(add);
    expect(text).toContain('The person is adding a printer.');
    expect(text).toContain('BBL/Bambu Lab A1 mini | Bambu Lab A1 mini | 180 × 180 × 180 mm\n');
    // A size nobody measured is a question mark, not a blank.
    expect(text).toContain('Vendor/Unmeasured | Vendor Unmeasured | ?\n');
    expect(text).not.toContain('The printer this is about');
  });

  it('state the printer the conversation is about, as it is now', () => {
    const text = printerInstructions(change);
    expect(text).toContain('Name: Lab Printer\n');
    expect(text).toContain('Brand and model: Bambu Lab A1 mini\n');
    expect(text).toContain('Nozzle: 0.4 mm (this model ships 0.2, 0.4, 0.6 and 0.8 mm)');
    expect(text).toContain('Loaded, as the printer reports it:\n- PLA Matte (PLA, #5f7d4f)\n- PETG (PETG)');
    expect(text).toContain('Connected to this app: yes\n');
    expect(text).toContain('Connects through: Bambu Lab LAN mode');
    expect(text).not.toContain('Printer list');
    expect(text).not.toContain('network plug-in');
  });

  it('state that the printer cannot be reached without the plug-in, when the app says so', () => {
    const printer = { ...change.context.printer!, needsNetworkPlugin: true };
    const text = printerInstructions({ ...change, context: { ...change.context, printer } });
    expect(text).toContain("Bambu's network plug-in: not installed, so nothing can reach this printer yet.");
    expect(text).not.toMatch(/button/);
  });

  it('claim nothing is loaded on a printer that is not connected', () => {
    const offline = session({ ...change, context: { printer: { ...change.context.printer!, spools: [], connected: false } } });
    const text = printerInstructions(offline);
    expect(text).toContain('Loaded, as the printer reports it: not known, as it is not connected\n');
    expect(text).toContain('Connected to this app: no\n');
  });

  it('say so when a connected printer reports nothing loaded', () => {
    const empty = session({ ...change, context: { printer: { ...change.context.printer!, spools: [] } } });
    expect(printerInstructions(empty)).toContain('Loaded, as the printer reports it: nothing\n');
  });

  it('name what is on the network', () => {
    const text = printerInstructions(session({ context: { printers: [], network: [{ name: 'Workshop', serial: '01P00A3B' }] } }));
    expect(text).toContain('On the network now: Workshop (01P00A3B)\n');
  });

  it('keep the rules that encode real constraints', () => {
    const text = printerInstructions(add);
    for (const rule of [
      'Start with just the printer model',
      'More than three fit',
      'is not one model',
      'never substitute a size',
      'alreadyYours means',
      'undid adding a printer, that printer is removed',
      'Do not add the same model again unless they ask for it',
      'Never ask for a password, access code or API key in chat',
      'a timeout means no response, not a wrong code',
      'answer anything the person says meanwhile',
      'name the three ways forward:',
      'try again with the same address',
      'set up the connection manually in the app',
      'Do not claim to open settings for them',
      'browse the full list manually in the app',
      'If the person asks to see the full printer list',
      'do not recite the list in chat or claim to open it for them',
      'leave it for now, as the printer can prepare prints without a connection',
      'nozzle mismatch reported by the printer',
      'when someone says what they loaded there is nothing to save',
      'call the tool without asking again',
      'ask first and stop: that reply calls no tool',
      // Measured: without the exact words, the offer came in 27-77% of replies
      // and its choices were mostly a bare "Yes | No".
      'end the reply to a successful printer_add with exactly "Want to connect it so you can send prints straight to it?" and then "Choices: Connect it | Not now"',
      'Do not add a Choices line',
      'it is safe to close this chat now',
      'after the person turns down connecting, after the app says the connection is verified, after they leave connecting for now, and after a successful printer_change',
      'they can close this chat now',
      'now slices for 0.6 mm.") and say they can close this chat now',
      'printer_connect opens a local form',
    ])
      expect(text.toLowerCase()).toContain(rule.toLowerCase());
  });

  it('offer no dialog or finish tool in any printer conversation', () => {
    for (const mode of ['add', 'change', 'connect'] as const) {
      const text = printerInstructions(session({ ...change, mode }));
      for (const removed of ['printer_manual_setup', 'printer_manual_connection', 'printer_setup_finish', 'Choices: Done'])
        expect(text).not.toContain(removed);
    }
  });

  it('send the rules for finding and adding a printer only while adding one', () => {
    const connect = session({ ...change, mode: 'connect' });
    for (const text of [printerInstructions(change), printerInstructions(connect)]) {
      expect(text).not.toContain('Rules for finding the printer');
      expect(text).not.toContain('printer_add');
      expect(text).toContain('Rules for changing a printer');
      expect(text).toContain('Rules for connecting a printer');
      expect(text).toContain('Rules for finishing');
    }
    expect(printerInstructions(add)).toContain('Rules for finding the printer');
  });

  it('keep the rule for a refused nozzle size in every session, since printer_change refuses one too', () => {
    const connect = session({ ...change, mode: 'connect' });
    for (const text of [printerInstructions(add), printerInstructions(change), printerInstructions(connect)])
      expect(text.match(/After unknown_nozzle, name the sizes supported/g)).toHaveLength(1);
  });

  it('say that the printer a change or a connection is about is already set up', () => {
    // Left to "Connected to this app: no", a change session offered to add
    // the printer it was about (2026-09-28).
    const connect = session({ ...change, mode: 'connect' });
    for (const text of [printerInstructions(change), printerInstructions(connect)])
      expect(text).toContain('This printer is already set up in this app: it can prepare prints now, connected or not.');
    expect(printerInstructions(add)).not.toContain('already set up in this app');
  });

  it('say which settings the tools change and where the rest are, for a printer the person has', () => {
    const connect = session({ ...change, mode: 'connect' });
    for (const text of [printerInstructions(change), printerInstructions(connect)]) {
      expect(text).toContain('read or change its other settings, such as start g-code');
      expect(text).toContain('is in its printer settings on this computer');
      expect(text).toContain('they can change it manually in the app; do not claim to open them');
      expect(text).toContain('Never give a reason you cannot help that the tools and the facts below do not state');
      expect(text).toContain('Their printer is already set up so they can prepare prints for it');
      // Measured: without it, "add my other printer too" got "Yes, I can add
      // it", which the app then refuses.
      expect(text).toContain('Another printer is not added here: say it is added with + Add printer on Home.');
    }
  });

  it('send the settings rules only to a session about a printer, and say a shipped profile is saved as a copy', () => {
    const connect = session({ ...change, mode: 'connect' });
    for (const text of [printerInstructions(change), printerInstructions(connect)]) {
      expect(text).toContain('Rules for changing its settings');
      expect(text).toContain('scope "printer" and target {"preset": the printer\'s name below}');
      expect(text).toContain('pass persistAs set to the printer\'s Name below, exactly as written there, not its brand and model');
      expect(text).toContain('when the facts below give a copy to save as, pass that name instead');
      expect(text).toContain('When a preview says read_only_preset');
      expect(text).not.toContain('Kind: the settings OrcaSlicer comes with');
    }
    expect(printerInstructions(add)).not.toContain('Rules for changing its settings');
    const stock = session({ ...change, context: { printer: { ...change.context.printer!, stock: true, copyName: 'Lab Printer - Copy' } } });
    expect(printerInstructions(stock)).toContain(
      'Kind: the settings OrcaSlicer comes with for this model, selected in the project, not a printer the person added.');
    expect(printerInstructions(stock)).toContain('Copy to save as: Lab Printer - Copy\n');
    expect(printerInstructions(change)).not.toContain('Copy to save as');
  });

  it('send adding a printer the goal it was measured with, and none of the other sessions\' words', () => {
    // Measured: the scope rule, or a goal naming all three sessions, made the
    // model ask about a printer named plainly instead of adding it.
