request=json.loads(pathlib.Path('/tmp/jusprin-core-prompt-request.json').read_text())
cases={
 'general-question':'What is PETG?',
 'project-advice':'Would the current material and print settings work for this part outdoors in summer? Just assess it for now.',
 'prepare-unknown-spool':'Prepare this model for printing. It is an indoor display piece. I have not told you which filament is loaded.',
 'changed-requirements':'I was going to use this indoors, but now it needs to survive sitting in a hot car. Are the current material and process settings still good candidates? Do not change anything yet.',
 'preserve-customization':'Prepare this indoor display piece for printing with the PLA I have loaded. Keep my custom settings if they are suitable.',
 'specific-change':'Set the layer height to 0.20 mm.'}
def run(item):
 name,user,repeat=item;b=copy.deepcopy(request)
 b['model']=m.MODEL;b['stream']=False;b['max_output_tokens']=2000
 b['provider']={'order':m.PROVIDERS,'allow_fallbacks':False}
 for msg in b['input']:
  if isinstance(msg.get('content'),str):msg['content']=msg['content'].replace('__USER_TEXT__',user)
  else:
   for p in msg.get('content',[]):
    if 'text' in p:p['text']=p['text'].replace('__USER_TEXT__',user)
 try:
  out={'case':name,'run':repeat,'output':[],'stop':'response_limit'}
  for step in range(3):
   r=m.post(b,os.environ['OPENROUTER_API_KEY'],m.ENDPOINT)
   output=r.get('output',[]);out['output']+=output;b['input']+=output
