    b['input'].append({'type':'function_call_output','call_id':call['call_id'],'output':json.dumps({'state':'succeeded','result':result,'actionId':'smoke-read','workspaceRevision':28})})
   if not replayed:break
 except Exception as e:out={'case':name,'run':repeat,'error':str(e)}
 return out
jobs=[(name,user,i) for name,user in cases.items() for i in (1,2)]
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as pool: results=list(pool.map(run,jobs))
pathlib.Path('/tmp/jusprin-core-prompt-smoke-results.json').write_text(json.dumps(results,indent=2))
